-- AQi Phase 3 — approved visual guidance, interactive tutorials, contextual onboarding,
-- document-backed knowledge and real analytics.
--
-- Design notes:
--   * A tutorial's steps are data, but every step references an id in the code target registry
--     (src/lib/aqi/targets.ts). No selector, script or executable UI command is stored here.
--   * Only one published version of a tutorial can exist at a time. Drafts never reach normal users.
--   * Progress is per person and workspace, separate from chat conversation persistence.
--   * Tutorial events are idempotent through a unique dedupe key and are append-only.
--   * Platform knowledge documents are management-only: no browser role receives a table grant,
--     and bytes live in private storage. The existing PDF/DOCX text extractor is reused.
--   * Nothing in this migration is applied to a hosted project by the repository.

-- ---------------------------------------------------------------------------
-- Safe analytics events: extend the existing AQi ledger instead of creating a second one.
-- ---------------------------------------------------------------------------
alter table aqi_usage_events add column if not exists metadata jsonb not null default '{}'::jsonb;
alter table aqi_usage_events add column if not exists intent text;
alter table aqi_usage_events drop constraint if exists aqi_usage_events_kind_check;
alter table aqi_usage_events add constraint aqi_usage_events_kind_check
  check (kind in (
    'message', 'feedback', 'config_publish', 'reservation', 'rate_limit',
    'knowledge_retrieval', 'knowledge_miss',
    'guidance_offer', 'guidance_accept', 'guidance_decline',
    'tip_view', 'tip_click'
  ));
create index if not exists aqi_usage_kind_created_idx on aqi_usage_events (kind, created_at desc);

-- ---------------------------------------------------------------------------
-- Tutorial definitions and versions
-- ---------------------------------------------------------------------------
create table if not exists aqi_tutorials (
  id uuid primary key default gen_random_uuid(),
  slug text not null unique check (slug ~ '^[a-z0-9]+(?:-[a-z0-9]+)*$' and char_length(slug) between 3 and 80),
  title text not null check (char_length(title) between 1 and 120),
  description text not null default '' check (char_length(description) <= 400),
  category text not null default 'Getting started' check (char_length(category) between 1 and 60),
  audience text[] not null default '{}',
  route_prefix text not null check (route_prefix ~ '^/[a-z0-9/_-]*$'),
  priority integer not null default 100 check (priority between 0 and 9999),
  status text not null default 'draft' check (status in ('draft', 'published', 'archived')),
  published_version_id uuid,
  created_by uuid references users(id) on delete set null,
  updated_by uuid references users(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists aqi_tutorials_status_idx on aqi_tutorials (status, priority, title);

create table if not exists aqi_tutorial_versions (
  id uuid primary key default gen_random_uuid(),
  tutorial_id uuid not null references aqi_tutorials(id) on delete cascade,
  version integer not null check (version > 0),
  status text not null default 'draft' check (status in ('draft', 'published', 'archived')),
  definition jsonb not null,
  notes text check (notes is null or char_length(notes) <= 500),
  created_by uuid references users(id) on delete set null,
  created_at timestamptz not null default now(),
  published_at timestamptz,
  published_by uuid references users(id) on delete set null,
  unique (tutorial_id, version)
);
-- One live version per tutorial, enforced by the database rather than by application ordering.
create unique index if not exists aqi_tutorial_one_published_version
  on aqi_tutorial_versions (tutorial_id) where status = 'published';

alter table aqi_tutorials drop constraint if exists aqi_tutorials_published_version_fk;
alter table aqi_tutorials add constraint aqi_tutorials_published_version_fk
  foreign key (published_version_id) references aqi_tutorial_versions(id) on delete set null;

-- ---------------------------------------------------------------------------
-- Per-person progress, deliberately separate from aqi_conversations
-- ---------------------------------------------------------------------------
create table if not exists aqi_tutorial_progress (
  id uuid primary key default gen_random_uuid(),
  org_id uuid references organizations(id) on delete cascade,
  user_id uuid not null references users(id) on delete cascade,
  tutorial_id uuid not null references aqi_tutorials(id) on delete cascade,
  tutorial_version integer not null check (tutorial_version > 0),
  attempt integer not null default 1 check (attempt > 0),
  current_step integer not null default 0 check (current_step >= 0),
  step_key text,
  status text not null default 'in_progress'
    check (status in ('in_progress', 'paused', 'completed', 'exited', 'unavailable')),
  unavailable_reason text check (unavailable_reason is null or char_length(unavailable_reason) <= 200),
  verified boolean not null default false,
  started_at timestamptz not null default now(),
  last_activity_at timestamptz not null default now(),
  completed_at timestamptz,
  updated_at timestamptz not null default now()
);
create unique index if not exists aqi_progress_user_tutorial_org
  on aqi_tutorial_progress (user_id, org_id, tutorial_id) where org_id is not null;
create unique index if not exists aqi_progress_user_tutorial_global
  on aqi_tutorial_progress (user_id, tutorial_id) where org_id is null;
create index if not exists aqi_progress_activity_idx on aqi_tutorial_progress (last_activity_at desc);

-- ---------------------------------------------------------------------------
-- Append-only tutorial analytics with idempotent identifiers
-- ---------------------------------------------------------------------------
create table if not exists aqi_tutorial_events (
  id uuid primary key default gen_random_uuid(),
  org_id uuid references organizations(id) on delete cascade,
  user_id uuid not null references users(id) on delete cascade,
  tutorial_id uuid not null references aqi_tutorials(id) on delete cascade,
  tutorial_version integer not null check (tutorial_version > 0),
  attempt integer not null default 1 check (attempt > 0),
  step_key text,
  kind text not null check (kind in (
    'started', 'step_viewed', 'step_completed', 'step_skipped', 'paused',
    'resumed', 'exited', 'completed', 'target_missing', 'restarted'
  )),
  dedupe_key text not null unique check (char_length(dedupe_key) between 8 and 240),
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now()
);
create index if not exists aqi_tutorial_events_lookup_idx
  on aqi_tutorial_events (tutorial_id, created_at desc);
create index if not exists aqi_tutorial_events_user_idx
  on aqi_tutorial_events (user_id, created_at desc);

-- ---------------------------------------------------------------------------
-- Onboarding and contextual-tip preferences (per person)
-- ---------------------------------------------------------------------------
create table if not exists aqi_user_preferences (
  user_id uuid primary key references users(id) on delete cascade,
  org_id uuid references organizations(id) on delete set null,
  onboarding_status text not null default 'not_seen'
    check (onboarding_status in ('not_seen', 'deferred', 'dismissed', 'completed', 'started')),
  onboarding_seen_at timestamptz,
  onboarding_dismissed_at timestamptz,
  postponed_until timestamptz,
  tips_enabled boolean not null default true,
  tips_quiet_until timestamptz,
  dismissed_tips text[] not null default '{}',
  updated_at timestamptz not null default now()
);

create table if not exists aqi_contextual_tips (
  id uuid primary key default gen_random_uuid(),
  slug text not null unique check (slug ~ '^[a-z0-9]+(?:-[a-z0-9]+)*$' and char_length(slug) between 3 and 80),
  route_prefix text not null check (route_prefix ~ '^/[a-z0-9/_-]*$'),
  title text not null check (char_length(title) between 1 and 120),
  body text not null check (char_length(body) between 1 and 300),
  roles text[] not null default '{}',
  permission text,
  tutorial_slug text,
  enabled boolean not null default true,
  priority integer not null default 100 check (priority between 0 and 9999),
  created_by uuid references users(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists aqi_tips_route_idx on aqi_contextual_tips (enabled, route_prefix, priority);

-- ---------------------------------------------------------------------------
-- Knowledge freshness metadata on the existing entries table
-- ---------------------------------------------------------------------------
alter table aqi_knowledge_entries add column if not exists last_reviewed_at timestamptz;
alter table aqi_knowledge_entries add column if not exists next_review_at timestamptz;
alter table aqi_knowledge_entries add column if not exists reviewed_by uuid references users(id) on delete set null;
alter table aqi_knowledge_entries add column if not exists review_note text
  check (review_note is null or char_length(review_note) <= 500);
alter table aqi_knowledge_entries add column if not exists freshness_days integer
  check (freshness_days is null or freshness_days between 7 and 3650);
alter table aqi_knowledge_entries add column if not exists source_kind text not null default 'manual'
  check (source_kind in ('manual', 'document'));
create index if not exists aqi_knowledge_review_idx on aqi_knowledge_entries (next_review_at) where status = 'published';

-- ---------------------------------------------------------------------------
-- Document ingestion metadata for platform knowledge (management only)
-- ---------------------------------------------------------------------------
create table if not exists aqi_knowledge_documents (
  id uuid primary key default gen_random_uuid(),
  knowledge_entry_id uuid references aqi_knowledge_entries(id) on delete set null,
  filename text not null check (char_length(filename) between 1 and 200),
  mime_type text not null check (char_length(mime_type) between 3 and 160),
  size_bytes integer not null check (size_bytes > 0 and size_bytes <= 20971520),
  sha256 text not null check (sha256 ~ '^[0-9a-f]{64}$'),
  storage_bucket text not null default 'company-documents' check (storage_bucket = 'company-documents'),
  storage_path text not null unique,
  extraction_status text not null default 'processing'
    check (extraction_status in ('processing', 'ready', 'failed', 'unsupported')),
  extraction_method text,
  extraction_detail text check (extraction_detail is null or char_length(extraction_detail) <= 500),
  extracted_text text check (extracted_text is null or char_length(extracted_text) <= 200000),
  extracted_chars integer check (extracted_chars is null or extracted_chars >= 0),
  risk_flags text[] not null default '{}',
  uploaded_by uuid references users(id) on delete set null,
  status text not null default 'draft' check (status in ('draft', 'linked', 'archived', 'deleted')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists aqi_knowledge_documents_status_idx on aqi_knowledge_documents (status, created_at desc);
create unique index if not exists aqi_knowledge_documents_sha on aqi_knowledge_documents (sha256) where status <> 'deleted';

alter table aqi_knowledge_entries drop constraint if exists aqi_knowledge_source_document_fk;
alter table aqi_knowledge_entries add column if not exists source_document_id uuid
  references aqi_knowledge_documents(id) on delete set null;

-- ---------------------------------------------------------------------------
-- Row level security and grants
-- ---------------------------------------------------------------------------
alter table aqi_tutorials enable row level security;
alter table aqi_tutorial_versions enable row level security;
alter table aqi_tutorial_progress enable row level security;
alter table aqi_tutorial_events enable row level security;
alter table aqi_user_preferences enable row level security;
alter table aqi_contextual_tips enable row level security;
alter table aqi_knowledge_documents enable row level security;

grant select on aqi_tutorials, aqi_tutorial_versions, aqi_contextual_tips to iaq_app_user;
grant select, insert, update, delete on aqi_tutorial_progress, aqi_user_preferences to iaq_app_user;
grant select, insert on aqi_tutorial_events to iaq_app_user;
-- No grant on aqi_knowledge_documents: it is reachable only through Super-Admin-checked server code.

drop policy if exists aqi_tutorials_published_select on aqi_tutorials;
create policy aqi_tutorials_published_select on aqi_tutorials for select to iaq_app_user
  using (status = 'published' and published_version_id is not null);

drop policy if exists aqi_tutorial_versions_published_select on aqi_tutorial_versions;
create policy aqi_tutorial_versions_published_select on aqi_tutorial_versions for select to iaq_app_user
  using (status = 'published' and exists (
    select 1 from aqi_tutorials t where t.id = tutorial_id and t.status = 'published' and t.published_version_id = aqi_tutorial_versions.id
  ));

drop policy if exists aqi_progress_owner_select on aqi_tutorial_progress;
create policy aqi_progress_owner_select on aqi_tutorial_progress for select to iaq_app_user
  using (user_id = app.current_user_id());
drop policy if exists aqi_progress_owner_insert on aqi_tutorial_progress;
create policy aqi_progress_owner_insert on aqi_tutorial_progress for insert to iaq_app_user
  with check (user_id = app.current_user_id());
drop policy if exists aqi_progress_owner_update on aqi_tutorial_progress;
create policy aqi_progress_owner_update on aqi_tutorial_progress for update to iaq_app_user
  using (user_id = app.current_user_id())
  with check (user_id = app.current_user_id());
drop policy if exists aqi_progress_owner_delete on aqi_tutorial_progress;
create policy aqi_progress_owner_delete on aqi_tutorial_progress for delete to iaq_app_user
  using (user_id = app.current_user_id());

drop policy if exists aqi_tutorial_events_owner_select on aqi_tutorial_events;
create policy aqi_tutorial_events_owner_select on aqi_tutorial_events for select to iaq_app_user
  using (user_id = app.current_user_id());
drop policy if exists aqi_tutorial_events_owner_insert on aqi_tutorial_events;
create policy aqi_tutorial_events_owner_insert on aqi_tutorial_events for insert to iaq_app_user
  with check (user_id = app.current_user_id());

drop policy if exists aqi_preferences_owner_select on aqi_user_preferences;
create policy aqi_preferences_owner_select on aqi_user_preferences for select to iaq_app_user
  using (user_id = app.current_user_id());
drop policy if exists aqi_preferences_owner_insert on aqi_user_preferences;
create policy aqi_preferences_owner_insert on aqi_user_preferences for insert to iaq_app_user
  with check (user_id = app.current_user_id());
drop policy if exists aqi_preferences_owner_update on aqi_user_preferences;
create policy aqi_preferences_owner_update on aqi_user_preferences for update to iaq_app_user
  using (user_id = app.current_user_id())
  with check (user_id = app.current_user_id());
drop policy if exists aqi_preferences_owner_delete on aqi_user_preferences;
create policy aqi_preferences_owner_delete on aqi_user_preferences for delete to iaq_app_user
  using (user_id = app.current_user_id());

drop policy if exists aqi_tips_enabled_select on aqi_contextual_tips;
create policy aqi_tips_enabled_select on aqi_contextual_tips for select to iaq_app_user
  using (enabled);

-- ---------------------------------------------------------------------------
-- Seed contextual tips (approved, configured copy; no model call is made to show one)
-- ---------------------------------------------------------------------------
insert into aqi_contextual_tips (slug, route_prefix, title, body, roles, permission, tutorial_slug, priority)
