  ('workforce-help', '/workforce', 'Meet your AI employees', 'AQi can show you where each employee lives and what its status means.', '{}', 'agents.use', 'view-ai-employees', 40),
  ('leads-help', '/leads', 'Need help with leads?', 'See the review queue, research requests and what approving a lead actually does.', '{owner,admin,member,sales_rep}', 'leads.view', 'manage-leads', 50),
  ('aqi-knowledge-help', '/admin/aqi', 'Want to learn how to update AQi knowledge?', 'Platform knowledge has drafts, review dates and document ingestion. AQi can show you where they are.', '{agency_super_admin}', null, 'aqi-knowledge', 60)
