-- Starter tutorial definitions are seeded below. Each definition references only approved target ids.
insert into aqi_tutorials (slug, title, description, category, audience, route_prefix, priority, status)
select slug, title, description, category, audience, route_prefix, priority, 'published'
from jsonb_to_recordset($seed$[{"slug":"getting-started","title":"Getting started with iAcquireOS","description":"A short tour of the workspace, your AI team and where to get help.","category":"Getting started","audience":[],"route_prefix":"/overview","priority":10,"definition":{"title":"Getting started with iAcquireOS","description":"A short tour of the workspace, your AI team and where to get help.","category":"Getting started","roles":[],"routePrefix":"/overview","priority":10,"aliases":["get started","getting started","new to iacquireos","quick tour","platform tour","show me around"],"keywords":["tour","welcome","overview","dashboard","start","navigation"],"steps":[{"key":"overview","title":"This is your workspace","body":"Overview brings your pipeline, appointments and AI team together. Every number here comes from real workspace data.","targetId":"overview.hero","route":"/overview"},{"key":"metrics","title":"The numbers that matter","body":"These tiles show what needs attention right now. Select a tile to open the page behind it.","targetId":"overview.kpis","route":"/overview"},{"key":"workforce-nav","title":"Meet your AI team","body":"AI Workforce is where your employees live. Select it in the navigation to continue.","targetId":"nav.workforce","route":null,"advance":"click"},{"key":"gallery","title":"Your employees","body":"Each employee has a role, a status and its own knowledge. Open an employee to chat or review its configuration.","targetId":"workforce.gallery","route":"/workforce"},{"key":"support-nav","title":"Help is always available","body":"Support is in the navigation. Select it to see how to reach the iAcquire team.","targetId":"nav.support","route":null,"advance":"click"},{"key":"support","title":"Start a real conversation","body":"This is the real Support page. A request is only created when you send it; AQi cannot create one for you.","targetId":"support.new-ticket","route":"/support"}],"completion":{"kind":"finish"}}},{"slug":"navigate-dashboard","title":"Navigating your dashboard","description":"Understand the overview tiles, next actions and AI team panel.","category":"Getting started","audience":[],"route_prefix":"/overview","priority":20,"definition":{"title":"Navigating your dashboard","description":"Understand the overview tiles, next actions and AI team panel.","category":"Getting started","roles":[],"routePrefix":"/overview","priority":20,"aliases":["navigate the dashboard","dashboard tour","where is everything","understand the dashboard"],"keywords":["dashboard","overview","metrics","navigation","tiles"],"steps":[{"key":"kpis","title":"Start with the tiles","body":"Each tile is a real count. A dash means the data source is not connected yet, not zero.","targetId":"overview.kpis","route":"/overview"},{"key":"actions","title":"Then check next actions","body":"This panel lists the most useful next steps for this workspace right now.","targetId":"overview.next-actions","route":"/overview"},{"key":"team","title":"Your AI team is one click away","body":"Open an employee to chat, or use Manage to review the whole workforce.","targetId":"overview.ai-team","route":"/overview"}],"completion":{"kind":"finish"}}},{"slug":"create-contact","title":"Adding your first contact","description":"Open Contacts, start a new contact and review the real form. AQi never submits it for you.","category":"CRM","audience":["owner","admin","member","sales_rep","support","appointment_setter"],"route_prefix":"/crm/contacts","priority":30,"definition":{"title":"Adding your first contact","description":"Open Contacts, start a new contact and review the real form. AQi never submits it for you.","category":"CRM","roles":["owner","admin","member","sales_rep","support","appointment_setter"],"routePrefix":"/crm/contacts","priority":30,"aliases":["add a contact","create a contact","new contact","adding a contact","add contact"],"keywords":["contact","contacts","crm","add","create"],"requiresCrm":{"capability":"contacts","provider":"native"},"steps":[{"key":"contacts-nav","title":"Open Contacts","body":"Contacts is under CRM in the navigation. Select it to continue.","targetId":"nav.crm.contacts","route":null,"advance":"click"},{"key":"new-contact","title":"Start a new contact","body":"Select New contact. The form opens over the list without leaving the page.","targetId":"crm.contacts.new","route":"/crm/contacts","advance":"click"},{"key":"first-name","title":"Enter the contact's details","body":"Start with a first name. Email and phone are optional, but a duplicate email or phone is flagged instead of creating a second record.","targetId":"crm.contact.first-name","route":"/crm/contacts"},{"key":"save","title":"Save it yourself","body":"When you are ready, choose Add contact. AQi does not press this button or submit the form; the walkthrough completes only when the new contact page opens.","targetId":"crm.contact.save","route":"/crm/contacts"}],"completion":{"kind":"route","pattern":"/crm/contacts/:id"}}},{"slug":"manage-leads","title":"Managing your leads","description":"Review researched leads, see their status and understand the review queue.","category":"CRM","audience":["owner","admin","member","sales_rep"],"route_prefix":"/leads","priority":40,"definition":{"title":"Managing your leads","description":"Review researched leads, see their status and understand the review queue.","category":"CRM","roles":["owner","admin","member","sales_rep"],"routePrefix":"/leads","priority":40,"aliases":["manage leads","review leads","lead review","where are my leads"],"keywords":["leads","lead","review","research","prospects"],"steps":[{"key":"leads-nav","title":"Open Leads","body":"Leads is in the main navigation. Select it to continue.","targetId":"nav.leads","route":null,"advance":"click"},{"key":"tabs","title":"Three lead views","body":"Review shows leads waiting for a decision, Researching shows requests in progress, and History keeps earlier decisions.","targetId":"leads.tabs","route":"/leads"},{"key":"review","title":"Review queue","body":"Select a lead to see its evidence, approve it or reject it. Approving is a real decision and is recorded.","targetId":"leads.review-table","route":"/leads"}],"completion":{"kind":"finish"}}},{"slug":"use-pipelines","title":"Using pipelines and deals","description":"See how pipeline stages work and where a new deal starts.","category":"CRM","audience":["owner","admin","member","sales_rep","appointment_setter"],"route_prefix":"/crm/pipelines","priority":50,"definition":{"title":"Using pipelines and deals","description":"See how pipeline stages work and where a new deal starts.","category":"CRM","roles":["owner","admin","member","sales_rep","appointment_setter"],"routePrefix":"/crm/pipelines","priority":50,"aliases":["create a pipeline","use pipelines","manage deals","add a deal","pipeline"],"keywords":["pipeline","pipelines","deal","deals","opportunity","stage"],"requiresCrm":{"capability":"opportunities","provider":"native"},"steps":[{"key":"pipelines-nav","title":"Open Pipelines","body":"Pipelines is under CRM in the navigation. Select it to continue.","targetId":"nav.crm.pipelines","route":null,"advance":"click"},{"key":"board","title":"The board","body":"Each column is a stage. Cards can be moved only by people with deal permissions, and every move is recorded.","targetId":"crm.pipelines.board","route":"/crm/pipelines"},{"key":"new-deal","title":"Start a deal","body":"New deal opens the deal form with the current pipeline selected. AQi will not create or move a deal for you.","targetId":"crm.pipelines.new-deal","route":"/crm/pipelines"}],"completion":{"kind":"finish"}}},{"slug":"manage-appointments-native","title":"Managing appointments","description":"Find the calendar, understand the views and where to book an appointment.","category":"Calendar","audience":["owner","admin","member","sales_rep","support","appointment_setter"],"route_prefix":"/crm/calendar","priority":60,"definition":{"title":"Managing appointments","descrip