$seed$::jsonb) as x(slug text, definition jsonb)
join aqi_tutorials t on t.slug = x.slug
on conflict (tutorial_id, version) do nothing;

update aqi_tutorials t
set published_version_id = v.id, updated_at = now()
from aqi_tutorial_versions v
where v.tutorial_id = t.id and v.version = 1 and t.published_version_id is null;

